/**
 * 播放列表存储 — 持久化到 data/playlists.json。
 *
 * 复用 preferences-store.ts 的模式：JSON 文件读写，文件不存在时返回空数组。
 * 歌单 id 用自增计数器（持久化在文件内的 nextId 字段），避免重启后 id 冲突。
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

/** 单个播放列表。 */
export type Playlist = {
	id: string;
	name: string;
	description: string;
	trackIds: string[];
	createdAt: string;
};

/** 文件结构：歌单列表 + 下一个 id 计数器。 */
type PlaylistsFile = {
	playlists: Playlist[];
	nextId: number;
};

const EMPTY_FILE: PlaylistsFile = { playlists: [], nextId: 1 };

const FILE_PATH = resolve('data/playlists.json');

/** 读取整个文件结构。文件不存在或解析失败时返回空结构。 */
async function readFileStructure(): Promise<PlaylistsFile> {
	try {
		const text = await readFile(FILE_PATH, 'utf8');
		const parsed = JSON.parse(text) as Partial<PlaylistsFile>;
		return {
			playlists: Array.isArray(parsed.playlists) ? parsed.playlists : [],
			nextId: typeof parsed.nextId === 'number' ? parsed.nextId : 1,
		};
	} catch {
		return { ...EMPTY_FILE };
	}
}

/** 写入文件结构。 */
async function writeFileStructure(data: PlaylistsFile): Promise<void> {
	await mkdir(dirname(FILE_PATH), { recursive: true });
	await writeFile(FILE_PATH, JSON.stringify(data, null, 2), 'utf8');
}

/** 读取所有播放列表（按创建时间升序）。 */
export async function readPlaylists(): Promise<Playlist[]> {
	const file = await readFileStructure();
	return file.playlists;
}

/** 追加一个播放列表，返回带 id 和 createdAt 的新歌单。 */
export async function appendPlaylist(
	name: string,
	description: string,
	trackIds: string[],
): Promise<Playlist> {
	const file = await readFileStructure();
	const playlist: Playlist = {
		id: `playlist-${String(file.nextId).padStart(3, '0')}`,
		name,
		description,
		trackIds,
		createdAt: new Date().toISOString(),
	};
	file.playlists.push(playlist);
	file.nextId += 1;
	await writeFileStructure(file);
	return playlist;
}

/** 按 id 删除播放列表，返回是否删除成功。 */
export async function removePlaylist(id: string): Promise<boolean> {
	const file = await readFileStructure();
	const before = file.playlists.length;
	file.playlists = file.playlists.filter((p) => p.id !== id);
	const removed = file.playlists.length < before;
	if (removed) await writeFileStructure(file);
	return removed;
}
