/**
 * Playlists route — 播放列表 CRUD 端点。
 *
 * - GET    /api/library/playlists          列出所有播放列表
 * - POST   /api/library/playlists          创建播放列表（name 必填，description/trackIds 可选）
 * - DELETE /api/library/playlists?id=<id>  删除指定播放列表
 *
 * 持久化到 data/playlists.json（server/library/playlists.ts），重启后不丢失。
 * 无效的 trackId（不在音乐库中）会被静默丢弃，只保留真实存在的曲目。
 */
import { getSongs } from '@/server/library';
import { appendPlaylist, readPlaylists, removePlaylist } from '@/server/library/playlists';
import { recordLocalInteraction } from '@/server/records/interaction-log';
import { ok, fail } from '@/server/http';

export async function GET() {
	const startedAt = Date.now();
	const playlists = await readPlaylists();
	const data = { playlists, count: playlists.length };
	void recordLocalInteraction({
		userInput: 'list playlists',
		intent: 'list_playlists',
		result: { count: data.count },
		latency: Date.now() - startedAt,
	});
	return ok(data);
}

export async function POST(request: Request) {
	const startedAt = Date.now();
	let body: { name?: unknown; description?: unknown; trackIds?: unknown };
	try {
		body = await request.json();
	} catch {
		return fail('Invalid JSON body', 400);
	}

	const name = typeof body.name === 'string' ? body.name.trim() : '';
	if (!name) {
		return fail('name is required', 400);
	}
	const description =
		typeof body.description === 'string' ? body.description.trim() : '';
	const rawTrackIds = Array.isArray(body.trackIds) ? body.trackIds : [];
	const songs = await getSongs();
	const songIds = new Set(songs.map((s) => s.id));
	const trackIds = rawTrackIds
		.filter((id): id is string => typeof id === 'string' && id.length > 0)
		.filter((id) => songIds.has(id));

	const playlist = await appendPlaylist(name, description, trackIds);

	const data = {
		playlist,
		trackCount: trackIds.length,
		totalLibrarySize: songs.length,
	};

	void recordLocalInteraction({
		userInput: `create playlist "${name}"`,
		intent: 'create_playlist',
		result: { playlistId: playlist.id, trackCount: data.trackCount },
		latency: Date.now() - startedAt,
	});

	return ok(data, 'ok', { status: 201 });
}

export async function DELETE(request: Request) {
	const startedAt = Date.now();
	const url = new URL(request.url);
	const id = url.searchParams.get('id');
	if (!id) {
		return fail('id query param is required', 400);
	}

	const removed = await removePlaylist(id);
	if (!removed) {
		return fail(`playlist not found: ${id}`, 404);
	}

	void recordLocalInteraction({
		userInput: `delete playlist ${id}`,
		intent: 'delete_playlist',
		result: { playlistId: id },
		latency: Date.now() - startedAt,
	});

	return ok({ id });
}
